// Some portions generated by Claude
package org.eclipse.rdf4j.opentelemetry;

import static org.assertj.core.api.Assertions.assertThat;

import org.eclipse.rdf4j.opentelemetry.repository.TracingRepository;
import org.eclipse.rdf4j.repository.Repository;
import org.eclipse.rdf4j.repository.base.RepositoryWrapper;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.sail.memory.MemoryStore;
import org.junit.jupiter.api.Test;

class OpenTelemetrySupportTest {

	@Test
	void instrument_wrapsPlainRepository() {
		Repository plain = new SailRepository(new MemoryStore());

		Repository traced = OpenTelemetrySupport.instrument(plain, "my-repo");

		assertThat(traced).isInstanceOf(TracingRepository.class);
	}

	@Test
	void instrument_alreadyTraced_doesNotWrapAgain() {
		Repository plain = new SailRepository(new MemoryStore());
		Repository traced = OpenTelemetrySupport.instrument(plain, "my-repo");

		Repository tracedAgain = OpenTelemetrySupport.instrument(traced, "my-repo");

		assertThat(tracedAgain).isSameAs(traced);
	}

	@Test
	void instrument_tracingRepositoryBehindDelegatingWrappers_doesNotWrapAgain() {
		Repository plain = new SailRepository(new MemoryStore());
		Repository traced = OpenTelemetrySupport.instrument(plain, "my-repo");
		// simulate further DelegatingRepository layers added on top of an already-traced repository, e.g. by a
		// RepositoryManager or other middleware
		Repository wrapped = new RepositoryWrapper(new RepositoryWrapper(traced));

		Repository result = OpenTelemetrySupport.instrument(wrapped, "my-repo");

		assertThat(result).isSameAs(wrapped);
	}
}
